const items = $input.all();
const seen = new Set();
const results = [];

const keywords = [
  "operations",
  "administration",
  "administrative",
  "human resources",
  "recruitment",
  "people operations",
  "executive assistant",
  "office manager",
  "project coordinator",
  "programme coordinator",
  "stakeholder",
  "budgeting",
  "records management",
  "process improvement",
  "automation",
  "n8n",
  "zapier",
  "google sheets",
  "workflow"
];

const countryCodes = {
  "united kingdom": "gb",
  "uk": "gb",
  "great britain": "gb",
  "australia": "au",
  "canada": "ca",
  "germany": "de",
  "nigeria": "ng"
};

const countryNames = {
  gb: "United Kingdom",
  au: "Australia",
  ca: "Canada",
  de: "Germany",
  ng: "Nigeria"
};

function safeText(value, fallback = "") {
  if (typeof value === "string") {
    const text = value.trim();
    return text && text !== "[object Object]"
      ? text
      : fallback;
  }

  if (typeof value === "number") return String(value);

  return fallback;
}

function addJob(job, source) {
  const suppliedCode = safeText(job.country_code).toLowerCase();
  const isNigeria = suppliedCode === "ng" ||
    safeText(job.country).toLowerCase() === "nigeria";

  const title = safeText(job.title);

  const company = safeText(
    job.company,
    safeText(job.company?.display_name, "Not specified")
  );

  const url = [
    job.application_url,
    job.redirect_url,
    job.adref
  ]
    .map(value => safeText(value))
    .find(value => /^https?:\/\/\S+$/i.test(value));

  if (!title || !url) return;

  // Remove repeated URLs within this run.
  const key = url.toLowerCase();
  if (seen.has(key)) return;
  seen.add(key);

  const description = safeText(job.description);

  const location = safeText(
    job.location,
    safeText(job.location?.display_name, "Not specified")
  );

  const areaCountry = Array.isArray(job.location?.area)
    ? safeText(job.location.area[0])
    : "";

  const rawCountry = isNigeria
    ? "Nigeria"
    : safeText(job.country, areaCountry);

  const countryCode =
    suppliedCode ||
    countryCodes[rawCountry.toLowerCase()] ||
    "";

  const country =
    countryNames[countryCode] ||
    rawCountry ||
    "Not specified";

  const text = `${title} ${description}`.toLowerCase();

  const matchedKeywords = keywords.filter(keyword => {
    const escaped = keyword.replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );

    return new RegExp(`\\b${escaped}\\b`, "i").test(text);
  });

  // Preliminary keyword signal only.
  // The next AI node performs the suitability assessment.
  const matchScore = Math.min(
    100,
    Math.round((matchedKeywords.length / 5) * 100)
  );

  results.push({
    json: {
      id: job.id || job.job_id || url,
      job_id: job.job_id || job.id || url,

      title,
      company,
      location,
      country,
      country_code: countryCode,

      description,
      work_arrangement: safeText(
        job.work_arrangement,
        "Not Specified"
      ),
      employment_type: safeText(job.employment_type),

      salary: safeText(job.salary),
      salary_min: job.salary_min ?? null,
      salary_max: job.salary_max ?? null,
      created: job.created || null,

      application_url: url,
      redirect_url: url,
      source,

      matched_keywords: matchedKeywords,
      keyword_match_score: matchScore,

      // Preserve this existing field for compatibility.
      cv_match_score: matchScore,
      match_score_basis:
        "Keyword overlap only; CV assessment pending",

      search_location_match: safeText(
        job.search_location_match
      ),
      nigeria_remote_eligibility: safeText(
        job.nigeria_remote_eligibility,
        "Not assessed"
      ),
      location_review: safeText(job.location_review),

      review_status: "Not reviewed",
      application_status: "Not applied",

      sponsorship_status: safeText(
        job.sponsorship_status,
        isNigeria ? "Not Required" : "Unconfirmed"
      )
    }
  });
}

for (const item of items) {
  const responses = Array.isArray(item.json)
    ? item.json
    : [item.json];

  for (const data of responses) {
    if (!data || typeof data !== "object") continue;

    if (Array.isArray(data.results)) {
      for (const job of data.results) {
        addJob(job, "Adzuna");
      }
    } else if (
      data.source === "Headcount Labs" ||
      safeText(data.country_code).toLowerCase() === "ng"
    ) {
      addJob(data, safeText(data.source, "Headcount Labs"));
    }
  }
}

return results;

const incoming = $('Prioritise Job Matches').all();
const existing = $('Get Existing Jobs').all();

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .split('?')[0]
    .replace(/\/+$/, '');
}

function getJobKey(value) {
  const cleaned = normalize(value);

  if (!cleaned) return '';

  if (/^(adzuna|url|headcount):/.test(cleaned)) {
    return cleaned;
  }

  const adzunaMatch = cleaned.match(
    /\/jobs\/(?:land\/ad|details)\/(\d+)/
  );

  if (adzunaMatch) {
    return 'adzuna:' + adzunaMatch[1];
  }

  return 'url:' + cleaned;
}

function getJobKeys(job) {
  const keys = new Set();

  const candidates = [
    job.job_id,
    job.id,
    job.application_url,
    job.redirect_url,
    job['Job ID'],
    job['Application URL'],
    job['Job URL']
  ];

  for (const candidate of candidates) {
    const key = getJobKey(candidate);
    if (key) keys.add(key);
  }

  const source = String(
    job.source ?? ''
  ).toLowerCase();

  if (source === 'headcount labs' && job.id) {
    keys.add('headcount:' + normalize(job.id));
  }

  return [...keys];
}

const saved = new Set();

for (const item of existing) {
  for (const key of getJobKeys(item.json)) {
    saved.add(key);
  }
}

const seen = new Set();
const output = [];

let alreadySavedCount = 0;
let repeatedThisRunCount = 0;
let invalidRecordCount = 0;

for (let index = 0; index < incoming.length; index++) {
  const job = incoming[index].json;
  const keys = getJobKeys(job);

  const applicationUrl = String(
    job.application_url || job.redirect_url || ''
  ).trim();

  if (
    !/^https?:\/\/\S+$/i.test(applicationUrl) ||
    keys.length === 0
  ) {
    invalidRecordCount++;
    continue;
  }

  const alreadySaved = keys.some(key => saved.has(key));

  if (alreadySaved) {
    alreadySavedCount++;
    continue;
  }

  const alreadySeen = keys.some(key => seen.has(key));

  if (alreadySeen) {
    repeatedThisRunCount++;
    continue;
  }

  for (const key of keys) {
    seen.add(key);
  }

  const primaryKey = getJobKey(applicationUrl);

  output.push({
    json: {
      ...job,
      job_id: primaryKey,
      search_result_type: 'job'
    }
  });
}

// New jobs continue through the normal saving route.
if (output.length > 0) {
  return output;
}

// Summary items must be routed to the notification,
// not to job validation or Google Sheets.
const checkedAt = $now
  .setZone('Africa/Lagos')
  .toFormat('dd LLLL yyyy, HH:mm');

const needsReview =
  invalidRecordCount > 0 || incoming.length === 0;

const subject = needsReview
  ? 'JobCompass: No new jobs — quality review needed'
  : 'JobCompass: Search completed — no new matches';

const explanation = needsReview
  ? 'No new jobs remained after duplicate checking. Some records were invalid or no records reached this step; review is needed.'
  : 'All job records reaching this step were already saved in your tracker. No duplicate rows were added.';

return [{
  json: {
    search_result_type: needsReview
      ? 'duplicate_check_review'
      : 'no_new_matches',

    checked_at: checkedAt,
    jobs_received: incoming.length,
    jobs_passed: incoming.length,
    new_jobs_count: 0,

    already_saved_count: alreadySavedCount,
    repeated_this_run_count: repeatedThisRunCount,
    invalid_record_count: invalidRecordCount,

    quality_review_required: needsReview,

    email_subject: subject,

    email_body: [
      'Hello Candidate,',
      '',
      `JobCompass reached duplicate checking on ${checkedAt} (Lagos time).`,
      '',
      `Job records checked: ${incoming.length}`,
      `Already in your tracker: ${alreadySavedCount}`,
      `Repeated within this run: ${repeatedThisRunCount}`,
      `Invalid records: ${invalidRecordCount}`,
      'New jobs to save: 0',
      '',
      explanation,
      '',
      'Your existing shortlist remains available in JobCompass.'
    ].join('\n')
  }
}];

const aiItems = $input.all();

const requiredFields = [
  "AI_MATCH_SCORE",
  "RECOMMENDATION",
  "SKILLS_MATCH",
  "SKILLS_GAPS",
  "ELIGIBILITY",
  "VISA_SPONSORSHIP",
  "RELOCATION_SUPPORT",
  "RECOMMENDATION_REASON"
];

const allowedRecommendations = [
  "Strong Match",
  "Good Match",
  "Possible Match",
  "Not Recommended"
];

function extractAssessment(response) {
  const assessment =
    response.text ??
    response.response?.generations?.[0]?.[0]?.text ??
    response.generations?.[0]?.[0]?.text ??
    response.response ??
    response.output ??
    "";

  return typeof assessment === "string"
    ? assessment
    : JSON.stringify(assessment);
}

function extractField(text, field) {
  const escaped = field.replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );

  // Do not let an empty field consume the next line.
  const pattern = new RegExp(
    `^[\\t ]*${escaped}[\\t ]*:[\\t ]*([^\\r\\n]*)`,
    "im"
  );

  return text.match(pattern)?.[1]?.trim() || "";
}

return aiItems.map((item, index) => {
  let sourceItem;

  try {
    sourceItem =
      $("Clean and Rank Jobs").itemMatching(index);
  } catch {
    throw new Error(
      `Cannot link AI assessment ${index + 1} to its original job. ` +
      "Preparation stopped to prevent mixing job records."
    );
  }

  if (!sourceItem?.json?.title) {
    throw new Error(
      `Original job is missing for AI assessment ${index + 1}.`
    );
  }

  const originalJob = sourceItem.json;
  const assessmentText = extractAssessment(item.json);
  const fields = {};

  for (const field of requiredFields) {
    fields[field] = extractField(assessmentText, field);
  }

  const warnings = [];

  if (!assessmentText.trim()) {
    warnings.push("AI assessment is empty");
  }

  const missingFields = requiredFields.filter(
    field => !fields[field]
  );

  if (missingFields.length) {
    warnings.push(
      "Missing assessment fields: " + missingFields.join(", ")
    );
  }

  const rawScore = fields.AI_MATCH_SCORE;

  const parsedScore = /^\d{1,3}$/.test(rawScore)
    ? Number(rawScore)
    : null;

  const scoreIsValid =
    parsedScore !== null &&
    parsedScore >= 0 &&
    parsedScore <= 100;

  if (!scoreIsValid) {
    warnings.push("Valid AI match score not found");
  }

  if (
    fields.RECOMMENDATION &&
    !allowedRecommendations.includes(fields.RECOMMENDATION)
  ) {
    warnings.push("Unrecognised recommendation");
  }

  const sponsorshipPattern =
    /^(Confirmed|Unconfirmed|Not Available|Not Required)\b/i;

  if (
    fields.VISA_SPONSORSHIP &&
    !sponsorshipPattern.test(fields.VISA_SPONSORSHIP)
  ) {
    warnings.push("Unrecognised sponsorship assessment");
  }

  if (
  fields.RELOCATION_SUPPORT &&
  !sponsorshipPattern.test(fields.RELOCATION_SUPPORT)
) {
  warnings.push("Unrecognised relocation assessment");
}

  const remoteMatch = fields.ELIGIBILITY.match(
    /Nigeria remote eligibility[\t ]*:[\t ]*(Confirmed|Unconfirmed|Excluded)\b/i
  );

  const appearsRemote =
    originalJob.search_location_match === "Remote" ||
    /^(remote|fully remote|remote[- ]only|100% remote)$/i
      .test(String(originalJob.work_arrangement ?? "").trim());

  const remoteEligibility = remoteMatch
    ? remoteMatch[1].charAt(0).toUpperCase() +
      remoteMatch[1].slice(1).toLowerCase()
    : appearsRemote
      ? "Unconfirmed"
      : "Not applicable";

  const assessmentValid = warnings.length === 0;

  const combinedWarnings = [
    originalJob.data_warning,
    ...warnings
  ].filter(Boolean);

  return {
    json: {
      ...originalJob,

      ai_assessment: assessmentText,

      // Invalid or incomplete assessments must not pass
      // a filter that checks the score alone.
      ai_match_score: assessmentValid ? parsedScore : null,
      ai_assessment_valid: assessmentValid,

      ai_recommendation: fields.RECOMMENDATION,
      ai_skills_match: fields.SKILLS_MATCH,
      ai_skills_gaps: fields.SKILLS_GAPS,
      ai_eligibility: fields.ELIGIBILITY,
      ai_visa_sponsorship: fields.VISA_SPONSORSHIP,
      ai_relocation_support: fields.RELOCATION_SUPPORT,
      ai_recommendation_reason: fields.RECOMMENDATION_REASON,

      // AI interpretation of the advert, not independent
      // verification of the employer's hiring arrangements.
      nigeria_remote_eligibility: remoteEligibility,
      remote_eligibility_basis: appearsRemote
        ? "AI assessment of supplied advert; human verification required"
        : "Not applicable",

      review_status: "Not reviewed",
      application_status: "Not applied",

      data_warning: combinedWarnings.join("; ")
    },
    pairedItem: {
      item: index
    }
  };
});

const jobs = $input.all();

function assessSponsorship(job) {
  const countryCode = String(
    job.country_code ?? ""
  ).trim().toLowerCase();

  const countryName = String(
    job.country ?? ""
  ).trim().toLowerCase();

  const isNigeria =
    countryCode === "ng" || countryName === "nigeria";

  const arrangement = String(
    job.work_arrangement ?? ""
  ).trim().toLowerCase();

  const isRemote =
    String(job.search_location_match ?? "")
      .trim().toLowerCase() === "remote" ||
    /^(remote|fully remote|remote[- ]only|100% remote)$/i.test(
      arrangement
    );

  const remoteEligibility = String(
    job.nigeria_remote_eligibility ?? ""
  ).trim().toLowerCase();

  // Assess remote work before using the vacancy's country.
  if (isRemote) {
    if (remoteEligibility === "confirmed") {
      return {
        ...job,
        sponsorship_status: "Not Required",
        sponsorship_evidence:
          "The supplied advert was assessed as permitting remote work from Nigeria. No relocation is proposed.",
        sponsorship_review:
          "Confirm the employer accepts Nigeria-based workers and the employment or contractor arrangement before accepting an offer."
      };
    }

    return {
      ...job,
      sponsorship_status: "Unconfirmed",
      sponsorship_evidence:
        "Remote work eligibility from Nigeria has not been established. The employer's country alone does not establish a visa requirement.",
      sponsorship_review: "Manual verification required"
    };
  }

  // Local work for the Nigerian candidate.
  if (isNigeria) {
    return {
      ...job,
      sponsorship_status: "Not Required",
      sponsorship_evidence:
        "Local Nigerian vacancy for a Nigerian applicant.",
      sponsorship_review: "Not Required"
    };
  }

  // Retain international checks for future search expansion.
  const description = String(job.description ?? "");
  const text = description.replace(/\s+/g, " ").trim();

  const negativePatterns = [
    /\bno (?:visa |work permit )?sponsorship(?: is)?(?: available| offered| provided)?\b/i,
    /\b(?:cannot|can't|unable to|will not|won't|do not|does not)\s+(?:offer|provide|support)\s+(?:visa |work permit )?sponsorship\b/i,
    /\b(?:not eligible|ineligible) for (?:visa |work permit )?sponsorship\b/i,
    /\b(?:visa |work permit )?sponsorship is not (?:available|offered|provided)\b/i
  ];

  const positivePatterns = [
    /\b(?:visa|work permit|skilled worker|tier 2) sponsorship (?:is )?(?:available|offered|provided)\b/i,
    /\b(?:we|employer|company) (?:can|will) (?:offer|provide) (?:visa |work permit )?sponsorship\b/i,
    /\bcertificate of sponsorship (?:is )?(?:available|provided)\b/i,
    /\b(?:lmia support|lmia sponsorship) (?:available|provided|offered)\b/i
  ];

  function findEvidence(patterns) {
    return patterns
      .map(pattern => text.match(pattern)?.[0])
      .filter(Boolean);
  }

  const negatives = findEvidence(negativePatterns);
  const positives = findEvidence(positivePatterns);

  const existingAuthorisationRequired =
    /\bmust (?:already )?have (?:the )?(?:right to work|work authori[sz]ation)\b/i.test(
      text
    );

  let status = "Unconfirmed";
  let evidence =
    "No explicit sponsorship offer or refusal found in the supplied description.";

  if (negatives.length && positives.length) {
    evidence =
      "Conflicting sponsorship wording: " +
      [...negatives, ...positives].join(" | ");
  } else if (negatives.length) {
    status = "Not Available";
    evidence = "Advert wording: " + negatives.join(" | ");
  } else if (positives.length) {
    status = "Confirmed";
    evidence = "Advert wording: " + positives.join(" | ");
  }

  if (existingAuthorisationRequired) {
    evidence +=
      " Existing work-authorisation wording also requires review.";
  }

  return {
    ...job,
    sponsorship_status: status,
    sponsorship_evidence: evidence,
    sponsorship_review:
      status === "Unconfirmed" || existingAuthorisationRequired
        ? "Manual verification required"
        : "Check original job advertisement"
  };
}

return jobs.map((item, index) => ({
  json: assessSponsorship(item.json),
  pairedItem: {
    item: index
  }
}));

const jobs = $input.all();

function getPriority(job) {
  const rawScore = job.ai_match_score;
  const score = Number(rawScore);

  const recommendation = String(
    job.ai_recommendation ?? ""
  ).trim().toLowerCase();

  const sponsorship = String(
    job.sponsorship_status ?? ""
  ).trim().toLowerCase();

  if (
    rawScore == null ||
    rawScore === "" ||
    !Number.isInteger(score) ||
    score < 0 ||
    score > 100 ||
    job.ai_assessment_valid !== true
  ) {
    return "Needs Review";
  }

  if (recommendation === "not recommended") {
    return "Not Recommended";
  }

  // Require the location checks performed upstream.
  if (
    job.relevance_status !== "Passed" ||
    job.location_filter_status !== "Passed"
  ) {
    return "Needs Review";
  }

  const arrangement = String(
    job.work_arrangement ?? ""
  ).trim().toLowerCase();

  const isRemote =
    String(job.search_location_match ?? "")
      .trim().toLowerCase() === "remote" ||
    /^(remote|fully remote|remote[- ]only|100% remote)$/i.test(
      arrangement
    );

  const remoteEligibility = String(
    job.nigeria_remote_eligibility ?? ""
  ).trim().toLowerCase();

  if (isRemote && remoteEligibility !== "confirmed") {
    return "Needs Review";
  }

  if (sponsorship === "not available") {
    return "Sponsorship Barrier";
  }

  // Important uncertainty must not become High Priority.
  if (recommendation === "possible match") {
    return "Needs Review";
  }

  if (
    recommendation !== "strong match" &&
    recommendation !== "good match"
  ) {
    return "Needs Review";
  }

  if (score >= 80) {
    return (
      sponsorship === "confirmed" ||
      sponsorship === "not required"
    )
      ? "High Priority"
      : "High Match - Verify Sponsorship";
  }

  if (score >= 65) {
    return "Medium Priority";
  }

  if (score >= 40) {
    return "Low Priority";
  }

  return "Not Recommended";
}

const priorityOrder = {
  "High Priority": 1,
  "High Match - Verify Sponsorship": 2,
  "Medium Priority": 3,
  "Low Priority": 4,
  "Needs Review": 5,
  "Sponsorship Barrier": 6,
  "Not Recommended": 7
};

return jobs
  .map((item, index) => ({
    json: {
      ...item.json,
      job_priority: getPriority(item.json)
    },
    pairedItem: {
      item: index
    }
  }))
  .sort((a, b) => {
    const rankA = priorityOrder[a.json.job_priority] ?? 99;
    const rankB = priorityOrder[b.json.job_priority] ?? 99;

    if (rankA !== rankB) {
      return rankA - rankB;
    }

    return (
      Number(b.json.ai_match_score || 0) -
      Number(a.json.ai_match_score || 0)
    );
  });

const searchGroups = [
  [
    {
      category: "Operations and Management",
      search_keyword: "operations manager"
    },
    {
      category: "Human Resources and Administration",
      search_keyword: "administrative officer"
    },
    {
      category: "Operations and Management",
      search_keyword: "project coordinator"
    }
  ],
  [
    {
      category: "Human Resources and Administration",
      search_keyword: "executive assistant"
    },
    {
      category: "Operations and Management",
      search_keyword: "operations coordinator"
    },
    {
      category: "AI Automation",
      search_keyword: "workflow automation"
    }
  ],
  [
    {
      category: "Operations and Management",
      search_keyword: "office manager"
    },
    {
      category: "Human Resources and Administration",
      search_keyword: "recruitment coordinator"
    },
    {
      category: "Digital Operations",
      search_keyword: "business operations"
    }
  ],
  [
    {
      category: "Operations and Management",
      search_keyword: "programme coordinator"
    },
    {
      category: "Human Resources and Administration",
      search_keyword: "HR officer"
    },
    {
      category: "Digital Operations",
      search_keyword: "process improvement"
    }
  ]
];

// Use the calendar date in Nigeria.
const today = $now
  .setZone("Africa/Lagos")
  .toISODate();

const date = new Date(today + "T00:00:00Z");
const dayIndex = Math.floor(
  date.getTime() / 86400000
);

// Monday, 5 January 1970 is the rotation anchor.
const weekIndex = Math.floor((dayIndex - 4) / 7);

// Monday = 0, Tuesday = 1, ... Sunday = 6.
const weekdayIndex = (date.getUTCDay() + 6) % 7;

// Five scheduled searches per week.
// Manual weekend runs reuse Friday's group.
const weekdaySlot = Math.min(weekdayIndex, 4);
const runIndex = weekIndex * 5 + weekdaySlot;

const groupIndex =
  ((runIndex % searchGroups.length) +
    searchGroups.length) %
  searchGroups.length;

return searchGroups[groupIndex].map(search => ({
  json: {
    country: "Nigeria",
    country_code: "ng",
    category: search.category,
    search_keyword: search.search_keyword
  }
}));

// Read every API response received by this node.
const jobs = $input.all().flatMap(item =>
  Array.isArray(item.json.data) ? item.json.data : []
);

function valueOf(field, fallback = "") {
  if (field === null || field === undefined) return fallback;

  if (typeof field === "object" && "value" in field) {
    return field.value ?? fallback;
  }

  return field;
}

function locationText(locations) {
  const raw = valueOf(locations, []);

  if (typeof raw === "string") return raw;
  if (!Array.isArray(raw)) return "";

  return raw.map(loc => {
    const location = valueOf(loc, {});

    if (typeof location === "string") return location;
    if (!location || typeof location !== "object") return "";

    return [
      valueOf(location.city),
      valueOf(location.state),
      valueOf(location.country)
    ].filter(Boolean).join(", ");
  }).filter(Boolean).join("; ");
}

function extractSalary(description) {
  const match = description.match(
    /Salary Range:\s*(₦[\d,]+\s*[–-]\s*₦[\d,]+\s*(?:monthly|annually|yearly)?)/i
  );

  return match ? match[1].trim() : "";
}

const results = [];

for (const job of jobs) {
  const rawPostings = valueOf(job.postings, []);
  const postings = Array.isArray(rawPostings)
    ? rawPostings.map(posting => valueOf(posting, {}))
    : [];

  let applicationUrl = "";

  for (const posting of postings) {
    const candidate =
      valueOf(posting?.application_url) ||
      valueOf(posting?.url) ||
      valueOf(posting?.posting_url);

    if (
      typeof candidate === "string" &&
      /^https?:\/\/\S+$/i.test(candidate.trim())
    ) {
      applicationUrl = candidate.trim();
      break;
