  const location = locationText(job.locations);

  const rawArrangement = valueOf(job.work_arrangement);

const arrangement =
  typeof rawArrangement === "string" && rawArrangement.trim()
    ? rawArrangement.trim()
    : "Not Specified";

  const isAbuja =
    /\bAbuja\b|\bFCT\b|\bFederal Capital Territory\b/i.test(location);

  // Use the structured field rather than assuming that any
  // mention of "remote" in the description describes the job.
  const isRemote =
    /^(remote|fully remote|remote[- ]only|100% remote)$/i.test(
      arrangement.trim()
    );

  // Keep Abuja jobs and remote candidates.
  if (!isAbuja && !isRemote) continue;

  const posting = postings[0] || {};

  results.push({
    json: {
      id: job.job_id,
      job_id: job.job_id,
      title: valueOf(job.title),
      company: valueOf(job.employer_name),

      location: location || "Location not specified",
      country: "Nigeria",
      country_code: "ng",

      description,
      work_arrangement: arrangement,
      employment_type: valueOf(posting.employment_type),
