  missing_source_information: 0,
  invalid_ai_assessment: 0,
  score_below_threshold: 0,
  invalid_score: 0,
  unsuitable_recommendation: 0,
  unpaid_or_volunteer: 0,
  excluded_occupation: 0,
  remote_eligibility_unconfirmed: 0,
  outside_abuja: 0
};

const excludedTitles = [
  /\bclinical coder\b/i,
  /\bregistered nurse\b/i,
  /\bmedical doctor\b/i,
  /\bsurgeon\b/i,
  /\bpharmacist\b/i,
  /\bqualified solicitor\b/i,
  /\bsenior software engineer\b/i
];

const allowedRecommendations = new Set([
  "strong match",
  "good match",
  "possible match"
]);

function text(value) {
  return typeof value === "string" ? value.trim() : "";
}

for (let index = 0; index < items.length; index++) {
  const job = items[index].json;

  const title = text(job.title);
  const description = text(job.description);
  const employmentType = text(job.employment_type);
  const applicationUrl =
    text(job.application_url) || text(job.redirect_url);

  if (
    !title ||
    !description ||
    !/^https?:\/\/\S+$/i.test(applicationUrl)
  ) {
    rejected.missing_source_information++;
    continue;
  }

  if (job.ai_assessment_valid !== true) {
    rejected.invalid_ai_assessment++;
    continue;
  }

  const rawScore = job.ai_match_score;
  const score = Number(rawScore);

  if (
    rawScore === null ||
    rawScore === undefined ||
    rawScore === "" ||
    !Number.isInteger(score) ||
    score < 0 ||
    score > 100
  ) {
    rejected.invalid_score++;
    continue;
  }

  if (score < MIN_SCORE) {
    rejected.score_below_threshold++;
    continue;
  }

  const recommendation = text(
    job.ai_recommendation
  ).toLowerCase();

  if (!allowedRecommendations.has(recommendation)) {
    rejected.unsuitable_recommendation++;
    continue;
  }

  const isUnpaid =
    /\bvolunteer\b|\bvoluntary\b|\bunpaid\b/i.test(title) ||
