    continue;
  }

  if (excludedTitles.some(pattern => pattern.test(title))) {
    rejected.excluded_occupation++;
    continue;
  }

  const location = text(job.location);
  const arrangement = text(
    job.work_arrangement
  ).toLowerCase();

  const isAbuja =
    /\bAbuja\b|\bFCT\b|\bFederal Capital Territory\b/i.test(
      location
    );

  const isNigeria =
    text(job.country_code).toLowerCase() === "ng" ||
    text(job.country).toLowerCase() === "nigeria";

  const isRemote =
    text(job.search_location_match).toLowerCase() === "remote" ||
    /^(remote|fully remote|remote[- ]only|100% remote)$/i.test(
      arrangement
    );

  const remoteEligibility = text(
    job.nigeria_remote_eligibility
  ).toLowerCase();

  let locationDecision;

  if (isRemote) {
    if (remoteEligibility !== "confirmed") {
      rejected.remote_eligibility_unconfirmed++;
      continue;
    }

    locationDecision =
      "Remote: supplied advert assessed as accepting Nigeria";
  } else {
    if (!isNigeria || !isAbuja) {
      rejected.outside_abuja++;
      continue;
    }

    locationDecision = "Abuja/FCT";
  }

  output.push({
    json: {
      ...job,
      search_result_type: "job",
      relevance_status: "Passed",
      relevance_score: score,
      relevance_threshold: MIN_SCORE,
